export class FormatFieldError extends Error {
  constructor(fieldName, value) {
    super(
      `Error in path (building) -> ${fieldName}\nstruct '<B' error during building, given value ${String(value)}`,
    );
    this.name = "FormatFieldError";
  }
}

function normalizeInteger(value, fieldName) {
  if (typeof value === "bigint") {
    return value;
  }

  if (typeof value === "number" && Number.isInteger(value)) {
    return BigInt(value);
  }

  throw new FormatFieldError(fieldName, value);
}

function toUnsignedByte(value, fieldName) {
  const normalized = normalizeInteger(value, fieldName);

  if (normalized < 0n || normalized > 255n) {
    throw new FormatFieldError(fieldName, value);
  }

  return Number(normalized);
}

export function buildTwoByteStruct(fields) {
  return [
    toUnsignedByte(fields.field1, "field1"),
    toUnsignedByte(fields.field2, "field2"),
  ];
}

